-- Eighth batch of explicitly labelled supplemental study outlines for MBH histology.
-- Idempotent: existing answers are never overwritten.
with supplemental_answers(id, answer) as (
  values
  ('b8e4cdce-a4a6-521c-9bbe-8145be3925cc', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). В коре мозжечка клетки Пуркинье получают возбуждающие сигналы от параллельных волокон зернистых клеток и мощные сигналы от лазящих волокон нижней оливы. Моховидные волокна через клубочки зернистого слоя активируют гранулярные клетки; клетки Гольджи, корзинчатые и звёздчатые клетки обеспечивают торможение. Пуркинье — единственные выходные нейроны коры и тормозят глубокие ядра. Глиоциты включают астроциты, олигодендроциты и микроглию; слои коры имеют характерную организацию.'),
  ('2594d337-1bb4-5938-b2cc-c357b0c1416c', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Соединительные ткани включают собственно соединительную, жировую, ретикулярную, хрящевую, костную и кровь. Ткани зуба и пародонта имеют соединительнотканные особенности: дентин — минерализованный матрикс с канальцами, цемент — минерализованная ткань корня, пульпа — рыхлая сосудисто-нервная соединительная ткань, периодонт — плотная волокнистая ткань с коллагеновыми пучками, альвеолярная кость — костная соединительная ткань. Они обеспечивают опору, питание, чувствительность и фиксацию зуба.'),
  ('0225f8ab-ef7e-5fbd-8bb6-daa7e27e92da', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Кожа включает эпидермис эктодермального происхождения и дерму мезодермального происхождения; гиподерма лежит глубже и содержит жировую ткань. На ладонях и подошвах кожа толстая, без волос и сальных желёз, с выраженным роговым слоем и эпидермальными гребнями. Кератинизация включает образование кератина, кератогиалина и корнеоцитов. Эпидермис обновляется базальными кератиноцитами. Рецепторы включают свободные нервные окончания, тельца Мейснера и Пачини, диски Меркеля и другие механорецепторы.'),
  ('4b355276-180d-5f02-97d9-4e9082e60b91', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Пульпа зуба — рыхлая соединительная ткань с сосудами, нервами, фибробластами и одонтобластами по периферии. Коронковая пульпа имеет более объёмную полость и выраженные рога; корневая пульпа располагается в канале и содержит сосудисто-нервные пучки, проходящие через апикальное отверстие. Одонтобласты образуют вторичный и третичный дентин; с возрастом полость пульпы сужается, фиброз и кальцификаты/дентикли могут нарастать. Кровоснабжение и иннервация идут через апикальное отверстие; воспаление вызывает выраженную боль из-за ограниченного пространства.'),
  ('c63202ff-a388-5ce5-9efd-b550d03e6452', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Матка имеет эндометрий, миометрий и периметрий; эндометрий включает функциональный и базальный слои, циклически изменяется под влиянием эстрогенов и прогестерона. Маточные трубы имеют складчатую слизистую с реснитчатыми и секреторными клетками, обеспечивают транспорт гамет/зиготы; влагалище покрыто многослойным плоским неороговевающим эпителием без желез в собственной стенке. Органы развиваются из парамезонефральных (мюллеровых) протоков; циклические изменения связаны с гормонами яичников.'),
  ('776e4879-f913-5e0a-98a6-9e49d574228e', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Матка развивается из слияния парамезонефральных протоков; её эндометрий изменяется в течение цикла: пролиферативная фаза под влиянием эстрогенов, секреторная — под влиянием прогестерона, менструация — при падении уровня гормонов. Маточные трубы имеют слизистую с высокими складками и реснитчатыми/секреторными клетками; влагалище — многослойный плоский неороговевающий эпителий и мышечно-соединительнотканную стенку. С возрастом меняются толщина эпителия и гормонозависимые свойства тканей.'),
  ('dcd1d083-b9f0-563e-ab74-e45ca67cb641', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Кора мозжечка состоит из трёх слоёв: молекулярного, слоя грушевидных клеток Пуркинье и зернистого. Клетки Пуркинье — главный выход коры мозжечка, их аксоны тормозят нейроны глубоких ядер. В зернистом слое находятся зернистые клетки и клетки Гольджи; в молекулярном — корзинчатые и звёздчатые клетки, а также дендриты Пуркинье и параллельные волокна. Белое вещество содержит миелиновые афферентные и эфферентные волокна; мозжечок координирует движение и равновесие.'),
  ('b4ee4e51-21c1-5df9-962a-11aa890c8739', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Молочная железа развивается как производное эпидермиса. В нелактирующем состоянии преобладают протоки и соединительнотканная строма, секреторные альвеолы слабо развиты; при беременности и лактации разрастаются дольки и альвеолы, клетки накапливают секрет. Белковый компонент молока выделяется преимущественно мерокриново, липидные капли — с участием апикальной мембраны. Пролактин стимулирует синтез молока, окситоцин вызывает сокращение миоэпителиальных клеток и выделение секрета.'),
  ('3b33dee5-7e77-5049-a67a-9fafe84adf82', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Неокортекс обычно имеет шесть слоёв: молекулярный, наружный зернистый, наружный пирамидный, внутренний зернистый, внутренний пирамидный и полиморфный. Цитоархитектоника описывает типы и распределение нейронов; в моторной коре выражен слой крупных пирамидных клеток, в сенсорной — зернистые слои. Миелоархитектоника описывает миелиновые волокна и горизонтальные/радиальные полосы. Колонки — вертикальные функциональные ансамбли нейронов, обрабатывающие связанные входы.'),
  ('2d16bd4f-0cb1-5818-99df-3e1327943d0b', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эпидермис происходит из эктодермы, дерма преимущественно из мезодермы, отдельные участки головы имеют вклад нервного гребня. Эпидермис — многослойный плоский ороговевающий эпителий; дерма — сосочковый рыхлый и сетчатый плотный соединительнотканные слои. Базальные кератиноциты обеспечивают физиологическое обновление. Кожные рецепторы воспринимают прикосновение, давление, вибрацию, температуру и боль; придатки включают волосы, ногти, сальные и потовые железы.'),
  ('908dfc64-d9b5-510a-bced-da35762247ae', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Волос развивается из эпидермального волосяного фолликула; матрикс луковицы делится и формирует стержень, меланоциты придают цвет, сосочек дермы обеспечивает трофическую поддержку. Сальные железы обычно открываются в фолликул и выделяют кожное сало голокриновым способом. Эккринные потовые железы открываются на поверхность кожи и участвуют в терморегуляции; апокринные связаны с определёнными областями и активируются с половым созреванием. Рост волос цикличен: анаген, катаген, телоген.'),
  ('6dfbb332-f864-59b4-bace-1a411797f3d2', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Лёгкие развиваются из энтодермального зачатка дыхательного эпителия и мезодермальных компонентов стромы, сосудов и хряща. Респираторный отдел включает респираторные бронхиолы, альвеолярные ходы и альвеолы; ацинус — участок дистальнее терминальной бронхиолы. Альвеолы выстланы пневмоцитами I типа для газообмена и II типа, синтезирующими сурфактант. Аэрогематический барьер включает тонкий слой пневмоцита I типа, слившиеся базальные мембраны и эндотелий капилляра. Лёгкие имеют двойное кровоснабжение: лёгочное и бронхиальное.'),
  ('2769aff8-57d3-5c8c-ab76-237994c3e142', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Кровеносные сосуды включают артерии, микроциркуляторное русло и вены. Артерии мышечного типа имеют развитую среднюю оболочку из циркулярных гладких миоцитов и регулируют распределение кровотока; вены имеют более тонкую медию, часто более выраженную адвентицию и служат ёмкостным резервуаром. В обоих типах различают интиму, медию и адвентицию. Гладкие миоциты сосудов меняют просвет под влиянием автономных нервов, гормонов и локальных медиаторов.'),
  ('84e5b227-25ad-50b1-a076-8184e3727057', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Высокое давление в артериях связано с толстой медией и эластическими элементами; в венах низкое давление, поэтому стенка тоньше, просвет шире, клапаны помогают направленному току. В артериях мышечного типа сокращение гладких миоцитов сужает просвет, расслабление расширяет; регуляция идёт через симпатическую иннервацию, гормоны и местные метаболиты. Регенерация сосудистой стенки ограничена, но эндотелий способен к пролиферации; с возрастом часто увеличивается жёсткость и меняется структура интимы/медии.'),
  ('3433d1e8-2cb1-50cb-a003-3ef396dfbf8f', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Лимфатический узел покрыт капсулой, от которой отходят трабекулы; строма образована ретикулярной тканью. В коре расположены B-клеточные фолликулы, в паракортикальной зоне — преимущественно T-лимфоциты, в мозговых тяжах — B-клетки, плазмоциты и макрофаги. Лимфа проходит через подкапсульный, корковые и мозговые синусы, где фильтруется и контактирует с антигенпредставляющими клетками. Узел обеспечивает иммунный ответ и фильтрацию лимфы.'),
  ('9d2193b6-37ca-535d-94ae-367bc37085f5', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Красный костный мозг — центральный орган кроветворения после рождения; его строма включает ретикулярные клетки, макрофаги, синусоидные капилляры и внеклеточный матрикс. В кроветворных островках клетки проходят пролиферацию и созревание, затем выходят в синусоиды. Гранулоцитопоэз включает миелобласт, промиелоцит, миелоцит, метамиелоцит, палочкоядерную и сегментоядерную стадии; моноцитопоэз — монобласт, промоноцит и моноцит.'),
  ('b28aaf63-4089-50b9-a3e9-449596e05dc3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Тромбоцитопоэз происходит в красном костном мозге: мегакариобласты проходят эндомитоз, становятся крупными полиплоидными мегакариоцитами, цитоплазма которых фрагментируется в тромбоциты. Тромбоциты — безъядерные фрагменты, участвующие в первичном гемостазе, адгезии и агрегации. Обычный взрослый референсный диапазон часто около 150–400 × 10⁹/л, но границы зависят от лаборатории. При описании препарата укажите мегакариоциты, синусоиды и кроветворные клетки.'),
  ('273b2ab9-eb63-5e77-b265-56697c28183a', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). У человека красный костный мозг — главный орган кроветворения, а тимус — центральный орган созревания T-лимфоцитов. У птиц B-лимфоциты созревают в фабрициевой сумке; у млекопитающих её функциональным аналогом служит красный костный мозг. B-клетки дифференцируются в плазмоциты и клетки памяти, T-клетки проходят селекцию в тимусе и становятся функциональными субпопуляциями. Периферические лимфоидные органы обеспечивают встречу лимфоцитов с антигенами.'),
  ('34da357d-6dbc-5d87-8767-2486c50462f0', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Ацинус лёгкого — функциональная единица газообмена, включающая респираторные бронхиолы, альвеолярные ходы, мешочки и альвеолы, связанные с одной терминальной бронхиолой. Пневмоциты I типа образуют тонкую поверхность для диффузии, пневмоциты II типа выделяют сурфактант и участвуют в восстановлении эпителия. Аэрогематический барьер состоит из цитоплазмы пневмоцита I типа, общей/слившейся базальной мембраны и эндотелия капилляра. Макрофаги удаляют частицы в просвете альвеол.'),
  ('c620c15e-63a2-5d57-88d8-01810ca7a3f3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Нёбные миндалины покрыты многослойным плоским неороговевающим эпителием, который образует глубокие крипты; под эпителием расположены лимфоидные фолликулы с герминативными центрами. Язычная миндалина покрыта эпителием спинки языка и имеет крипты, обычно менее глубокие; слизистые железы помогают очищать крипты. Миндалины входят в лимфоидное кольцо глотки, обеспечивают контакт антигенов с лимфоцитами и местную иммунную защиту.')
)
update public.exam_questions q
set answer = s.answer, updated_at = now()
from supplemental_answers s
where q.id = s.id::uuid
  and q.subject_slug = 'histology'
  and nullif(btrim(q.answer), '') is null;
